import formatMoney from './format-money';
import { getLogger } from '~/lib/log';
import { storeKeys } from '../mixins/base-listing-mixin';

const log = getLogger('searchProductData');

export default function searchProductData(config = {}) {
  const base = storeKeys(config);

  return {
    ...base,
    products: [],
    hasNextPage: false,
    hasPreviousPage: false,
    endCursor: null,
    startCursor: null,
    pageStartCursor: null,
    pageEndCursor: null,

    searchService: null,
    moneyFormatter: formatMoney,

    searchQuery: '',
    availableFilter: [],
    selectedFilters: {},

    loading: false,
    infiniteScrollLoading: false,
    error: null,

    toast: {
      visible: false,
      message: '',
    },

    filteropen: false,
    locale: {},

    lastScrollLoadTime: 0,
    scrollThrottleMs: 800,

    currentSort: {
      key: 'RELEVANCE',
      labelkey: 'featured',
      sortKey: 'RELEVANCE',
      reverse: false,
    },

    sortOptions: [
      {
        key: 'RELEVANCE', labelkey: 'featured', sortKey: 'RELEVANCE', reverse: false,
      },
      {
        key: 'PRICE_ASC', labelkey: 'price_low_high', sortKey: 'PRICE', reverse: false,
      },
      {
        key: 'PRICE_DESC', labelkey: 'price_high_low', sortKey: 'PRICE', reverse: true,
      },
    ],

    //------------------------------------
    // INIT
    //------------------------------------
    async init() {
      this.locale = JSON.parse(document.getElementById('sorting-locale').textContent);
      this.enableAutoload = config.enableAutoLoad === true || config.enableAutoLoad === 'true';

      const factory = this.createStorefrontFactory();
      this.searchService = factory.createSearchService();
      const urlParams = new URLSearchParams(window.location.search);
      this.searchQuery = urlParams.get('q') || config.searchQuery || '';
      const hasFilterParams = Array.from(urlParams.keys()).some(
        (key) => key.startsWith('filter.') || key.startsWith('sort_by') || key.endsWith('_cursor'),
      );
      this.$watch('products', () => {
        this.updatePageTitle();
      });

      if (hasFilterParams) {
        await this.loadProductsWithUrlFilters(urlParams);
      } else {
        await this.loadInitialProductsAndFilters();
      }

      this.updatePageTitle();
    },

    updatePageTitle() {
      const count = this.products ? this.products.length : 0;
      const searchTerm = this.searchQuery || 'Search';
      const shopName = document.querySelector('meta[property="og:site_name"]')?.content || 'Shop';

      document.title = `Search: ${count} results found for "${searchTerm}" – ${shopName}`;
    },

    //------------------------------------
    // LOADING FILTERS + PRODUCTS
    //------------------------------------

    async loadAvailableFilters() {
      const baseResult = await this.searchService.getavailableFilters(
        this.searchQuery,
        { first: 1 },
      );
      this.availableFilter = baseResult?.availableFilter || [];
    },

    async loadInitialProductsAndFilters() {
      if (!this.searchService) {
        return;
      }

      try {
        this.setLoadingState(true);

        const result = await this.searchService.getProducts(this.searchQuery, {
          first: Number(this.productsPerPage),
        });
        this.applyResult(result);
      } catch (error) {
        log.error('Error loading search products:', error);
        this.error = error.message;
      } finally {
        this.loading = false;
      }
    },

    //------------------------------------
    // URL-FILTER LOADING
    //------------------------------------

    async loadProductsWithUrlFilters(urlParams) {
      if (!this.searchService) {
        return;
      }

      this.setLoadingState(true);
      let filtersPayload = [];
      this.selectedFilters = {};

      try {
        await this.loadAvailableFilters();

        filtersPayload = [
          ...this.extractSelectedFilters(urlParams),
          ...this.extractPriceRangeFilters(urlParams),
        ];
        this.extractSortOptions(urlParams);

        const pagination = this.buildPaginationPayload(urlParams);

        const result = await this.searchService.getProducts(
          this.searchQuery,
          {
            ...pagination,
            filters: filtersPayload,
          },
        );

        this.applyResult(result);
      } catch (error) {
        log.error('Error loading URL-filtered search products:', error);
        this.error = error.message;
      } finally {
        this.loading = false;
      }
    },

    //------------------------------------
    // RESULT HANDLER
    //------------------------------------

    applyResult(result) {
      this.products = result?.products || [];
      this.availableFilter = result?.availableFilter || this.availableFilter;

      const pageInfo = result?.pageInfo ?? {};
      this.hasNextPage = pageInfo.hasNextPage || false;
      this.hasPreviousPage = pageInfo.hasPreviousPage || false;
      this.startCursor = pageInfo.startCursor || null;
      this.endCursor = pageInfo.endCursor || null;
    },

    //------------------------------------
    // FILTER PARSING
    //------------------------------------

    extractSelectedFilters(urlParams) {
      const filters = [];
      urlParams.forEach((value, key) => {
        const filterId = `${key}.${value}`;

        this.availableFilter.forEach((filter) => {
          filter.values.forEach((v) => {
            if (v.id === filterId) {
              this.selectedFilters[filter.label] ||= [];
              this.selectedFilters[filter.label].push(v);

              try {
                filters.push(JSON.parse(v.input));
              } catch (err) {
                log.warn('Failed to parse input for', v.label, err);
              }
            }
          });
        });
      });

      return filters;
    },

    extractPriceRangeFilters(urlParams) {
      const priceMin = urlParams.get('filter.price_min');
      const priceMax = urlParams.get('filter.price_max');

      if (!priceMin && !priceMax) {
        return [];
      }

      const min = parseFloat(priceMin || 0);
      const max = parseFloat(priceMax || 1000);

      this.selectedFilters.PriceMin = min;
      this.selectedFilters.PriceMax = max;

      return [{ price: { min, max } }];
    },

    extractSortOptions(urlParams) {
      const sortValue = Array.from(urlParams.values()).find((v) =>
        this.sortOptions.some((s) => s.key === v),
      );

      if (!sortValue) {
        return;
      }

      this.currentSort = this.sortOptions.find((s) => s.key === sortValue);
    },

    buildPaginationPayload(urlParams) {
      return {
        first: Number(this.productsPerPage),
        last: Number(this.productsPerPage),
        sortKey: this.currentSort.sortKey,
        reverse: this.currentSort.reverse,
        after: urlParams.get('start_cursor') || null,
        before: urlParams.get('end_cursor') || null,
      };
    },

    //------------------------------------
    // APPLY SORT + FILTER
    //------------------------------------

    applySort(option) {
      this.currentSort = { ...option };
      this.pageStartCursor = null;
      this.pageEndCursor = null;
      this.applyFilters();
    },

    async applyFilters() {
      try {
        this.startLoading();

        const options = this.buildQueryOptions();
        await this.loadAvailableFilters();
        await this.loadProducts(options);

        this.updateUrlParams();
      } catch (error) {
        this.handleError(error);
      } finally {
        this.loading = false;
      }
    },

    startLoading() {
      this.setLoadingState(true);
      this.products = [];
    },

    buildQueryOptions() {
      const urlParams = new URLSearchParams(window.location.search);

      return {
        filters: this.getFiltersPayload(),
        first: Number(this.productsPerPage),
        last: Number(this.productsPerPage),
        sortKey: this.currentSort.sortKey,
        reverse: this.currentSort.reverse,
        after: urlParams.get('start_cursor'),
        before: urlParams.get('end_cursor'),
      };
    },

    async loadProducts(options) {
      const result = await this.searchService.getProducts(
        this.searchQuery,
        options,
      );

      this.products = result?.products ?? [];

      const pageInfo = result?.pageInfo ?? {};
      this.hasNextPage = pageInfo.hasNextPage ?? false;
      this.hasPreviousPage = pageInfo.hasPreviousPage ?? false;
      this.startCursor = pageInfo.startCursor ?? null;
      this.endCursor = pageInfo.endCursor ?? null;
    },

    handleError(error) {
      this.error = error.message;
      log.error('Error applying filters:', error);
    },

    //------------------------------------
    // TOGGLE FILTER
    //------------------------------------

    toggleFilter(label, value, input, id) {
      this.selectedFilters[label] ||= [];
      const index = this.selectedFilters[label].findIndex((v) => v.label === value);

      if (index === -1) {
        this.selectedFilters[label].push({ label: value, input, id });
      } else {
        this.selectedFilters[label].splice(index, 1);
        if (this.selectedFilters[label].length === 0) {
          delete this.selectedFilters[label];
        }
      }

      const url = new URL(window.location.href);
      Array.from(url.searchParams.keys()).forEach((key) => {
        if (
          key.startsWith('filter.')
          || key.startsWith('price_')
          || key.endsWith('_cursor')
        ) {
          url.searchParams.delete(key);
        }
      });
      this.applyFilters();
    },

    removeSingleFilter(label, filterObj) {
      if (this.selectedFilters[label]) {
        const index = this.selectedFilters[label].findIndex((f) => f.id === filterObj.id);
        if (index !== -1) {
          this.selectedFilters[label].splice(index, 1);
        }

        if (this.selectedFilters[label].length === 0) {
          delete this.selectedFilters[label];
        }
      }

      const url = new URL(window.location.href);
      Array.from(url.searchParams.keys()).forEach((key) => {
        if (
          key.startsWith('filter.')
          || key.startsWith('price_')
          || key.endsWith('_cursor')
        ) {
          url.searchParams.delete(key);
        }
      });
      this.applyFilters();
      this.updateUrlParams();
    },

    clearAllFilters() {
      this.selectedFilters = {};
      this.products = [];
      const url = new URL(window.location.href);
      Array.from(url.searchParams.keys()).forEach((key) => {
        if (
          key.startsWith('filter.')
          || key.startsWith('price_')
          || key.endsWith('_cursor')
        ) {
          url.searchParams.delete(key);
        }
      });
      this.applyFilters();
      this.updateUrlParams();
    },

    //------------------------------------
    // PAGINATION - INFINITE SCROLL
    //------------------------------------

    async nextPage(isInfinite = false) {
      if (!this.searchService) {
        return;
      }

      if (this.loading) {
        return;
      }

      // eslint-disable-next-line no-negated-condition
      if (!isInfinite) {
        this.setLoadingState(true);
      } else {
        const now = Date.now();
        if (now - this.lastScrollLoadTime < this.scrollThrottleMs) {
          return;
        }

        this.lastScrollLoadTime = now;
        this.infiniteScrollLoading = true;
      }

      this.pageEndCursor = null;

      const filtersPayload = this.getFiltersPayload();
      const object = {
        filters: filtersPayload,
        first: Number(this.productsPerPage),
        sortKey: this.currentSort.sortKey,
        reverse: this.currentSort.reverse,
        after: this.endCursor,
      };

      try {
        const result = await this.searchService.getProducts(this.searchQuery, object);
        const productsData = result?.products;

        if (productsData) {
          if (isInfinite) {
            // FIXED: Only add products that aren't already in the array (avoid duplicates)
            const existingIds = new Set(this.products.map((p) => p.id));
            const newProducts = productsData.filter((p) => !existingIds.has(p.id));

            log.debug(`debugInfinite scroll: Got ${productsData.length} products, adding ${newProducts.length} new ones`);

            this.products.push(...newProducts);
          } else {
            this.products = productsData;
            this.pageStartCursor = this.endCursor;
            this.updateUrlParams();
          }

          const pageInfo = result?.pageInfo;
          this.hasNextPage = pageInfo.hasNextPage;
          this.hasPreviousPage = pageInfo.hasPreviousPage;
          this.startCursor = pageInfo.startCursor;
          this.endCursor = pageInfo.endCursor;
        }
      } catch (err) {
        log.error('Error fetching next page:', err);
      } finally {
        this.loading = false;
        this.infiniteScrollLoading = false;
      }
    },

    async prevPage() {
      if (!this.searchService || this.loading) {
        return;
      }

      this.setLoadingState(true);
      this.pageStartCursor = null;

      const filtersPayload = this.getFiltersPayload();

      const object = {
        filters: filtersPayload,
        last: Number(this.productsPerPage),
        sortKey: this.currentSort.sortKey,
        reverse: this.currentSort.reverse,
        before: this.startCursor,
      };
      this.pageEndCursor = this.startCursor;

      try {
        const result = await this.searchService.getProducts(this.searchQuery, object);
        const productsData = result?.products;

        if (productsData) {
          this.products = productsData;
          const pageInfo = result?.pageInfo;
          this.hasNextPage = pageInfo.hasNextPage;
          this.hasPreviousPage = pageInfo.hasPreviousPage;
          this.startCursor = pageInfo.startCursor;
          this.endCursor = pageInfo.endCursor;
        }

        this.updateUrlParams();
      } catch (err) {
        log.error('Error fetching previous page:', err);
      } finally {
        this.loading = false;
      }
    },

    //------------------------------------
    // URL UPDATES
    //------------------------------------

    updateUrlParams() {
      const url = new URL(window.location.href);

      Array.from(url.searchParams.keys()).forEach((key) => {
        if (
          key.startsWith('filter.')
          || key.startsWith('price_')
          || key === 'sort_by'
          || key.endsWith('_cursor')
        ) {
          url.searchParams.delete(key);
        }
      });

      Object.entries(this.selectedFilters).forEach(([label, values]) => {
        // eslint-disable-next-line max-statements-per-line
        if (label === 'PriceMin' || label === 'PriceMax') { /* empty */ } else if (Array.isArray(values)) {
          values.forEach((v) => {
            const parts = v.id.split('.');
            const key = parts.slice(0, -1).join('.');
            const val = parts[parts.length - 1];
            url.searchParams.append(key, val);
          });
        }
      });

      if (this.selectedFilters.PriceMin !== undefined) {
        url.searchParams.set('filter.price_min', this.selectedFilters.PriceMin);
      }

      if (this.selectedFilters.PriceMax !== undefined) {
        url.searchParams.set('filter.price_max', this.selectedFilters.PriceMax);
      }

      if (this.currentSort && this.currentSort.key) {
        url.searchParams.set('sort_by', this.currentSort.key);
      }

      if (this.pageStartCursor) {
        url.searchParams.set('start_cursor', this.pageStartCursor);
      } else {
        url.searchParams.delete('start_cursor');
      }

      if (this.pageEndCursor) {
        url.searchParams.set('end_cursor', this.pageEndCursor);
      } else {
        url.searchParams.delete('end_cursor');
      }

      window.history.replaceState({}, '', url);
    },

    //------------------------------------
    // HELPERS
    //------------------------------------

    setLoadingState(state) {
      this.loading = state;
      if (state) {
        this.products = [];
      }
    },

    showToast(message, type = 'error') {
      this.toast.message = message;
      this.toast.visible = true;
      this.toast.type = type;
      setTimeout(() => {
        this.toast.visible = false;
      }, 2500);
    },

    getFiltersPayload() {
      const filtersPayload = [];
      Object.entries(this.selectedFilters).forEach(([label, values]) => {
        // eslint-disable-next-line max-statements-per-line
        if (label === 'PriceMin' || label === 'PriceMax') { /* empty */ } else if (Array.isArray(values)) {
          values.forEach((v) => {
            try {
              filtersPayload.push(JSON.parse(v.input));
            } catch (err) {
              log.warn('Failed to parse filter input:', v.input, err);
            }
          });
        }
      });

      if (this.selectedFilters.PriceMin !== undefined || this.selectedFilters.PriceMax !== undefined) {
        const priceFilter = this.availableFilter.find((f) => f.type === 'PRICE_RANGE');
        if (priceFilter) {
          const priceData = JSON.parse(priceFilter.values[0].input).price;
          const min = this.selectedFilters.PriceMin ?? priceData.min;
          const max = this.selectedFilters.PriceMax ?? priceData.max;
          filtersPayload.push({ price: { min, max } });
        }
      }

      return filtersPayload;
    },
  };
}
